/// <summary>
/// CoC extension
/// MPJ_15465_DirectDebitAutomation
/// </summary>
[ExtensionOf(classStr(CustVendPaymProposal))]
final class METCustVendPaymProposal_Extension
{

}

Method.Source:
    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_custVendTransOpen">_custVendTransOpen</param>
    /// <param name = "_paymDate">_paymDate</param>
    /// <param name = "_paymCurrency">_paymCurrency</param>
    /// <returns>CustVendPaymProposalLine</returns>
    public CustVendPaymProposalLine buildPaymProposalLine(
        CustVendTransOpen   _custVendTransOpen,
        TransDate           _paymDate,
        CurrencyCode        _paymCurrency)
    {        
        CustVendPaymProposalLine proposalLine = next buildPaymProposalLine(
            _custVendTransOpen,
            _paymDate,
            _paymCurrency);

        if(this.ledgerJournalType() == LedgerJournalType::CustPayment)
        {
            boolean addLine = true;
            changecompany(_custVendTransOpen.DataArea)
            {
                CustDispute custDispute = CustDispute::findByCustTrans(_custVendTransOpen.RefRecId);
                if(custDispute)
                {
                    if( custDispute.Status == CustVendDisputeStatus::Disputed ||
                        custDispute.Status == CustVendDisputeStatus::PromiseToPay)
                    {
                        addLine = false;
                    }
                }

                //MPJ_18632
                CustTrans       metCustTrans = CustTrans::findByCompany(_custVendTransOpen.DataArea, _custVendTransOpen.RefRecId);
                CustTable       metCustTable = CustTable::find(metCustTrans.AccountNum);
                if (metCustTable.PaymMode == METConstants::AMEX &&
                    metCustTable.PaymMode != metCustTrans.paymMode &&
                    metCustTrans.RecId)
                {
                    ttsbegin;
                    metCustTrans.selectForUpdate(true);
                    metCustTrans.PaymMode = metCustTable.PaymMode;
                    metCustTrans.PaymModeMap::modifiedPaymMode();
                    metCustTrans.update();

                    proposalLine.PaymMode = metCustTable.PaymMode;
                    ttscommit;
                }

            }
            if(!addLine)
            {
                proposalLine.AccountNum = ''; // Bypass addition of line
            }
        }        
        return proposalLine;
    }
